public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int operations = 0;
    while (!allEqual(arr)) {
        operations++;
        int minVal = findMin(arr);
        int maxVal = findMax(arr);
        arr[minVal] -= 1;
        arr[maxVal] += 1;
    }
    return operations;
}

private boolean allEqual(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[i - 1]) {
            return false;
        }
    }
    return true;
}

private int findMin(int[] arr) {
    int min = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

private int findMax(int[] arr) {
    int max = arr[0];
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

