public int findMinFibonacciNumbers(int k) {
  int[] fibonacciNumbers = { 1, 1 };
  int i = 2;
  int sum = 0;
  while (sum < k) {
    fibonacciNumbers[i] = fibonacciNumbers[i - 1] + fibonacciNumbers[i - 2];
    i++;
    sum += fibonacciNumbers[i];
  }
  int count = 0;
  while (k > 0) {
    int index = Arrays.binarySearch(fibonacciNumbers, k);
    if (index < 0) {
      index = -index - 1;
    }
    count++;
    k -= fibonacciNumbers[index];
  }
  return count;
}

