public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        boolean isSteppingNumber = true;
        List<Integer> digits = getDigits(i);
        for (int j = 1; j < digits.size(); j++) {
            if (!compareDigits(digits.get(j - 1), digits.get(j))) {
                isSteppingNumber = false;
                break;
            }
        }
        if (isSteppingNumber) {
            steppingNumbers.add(i);
        }
    }
    return steppingNumbers;
}

private static List<Integer> getDigits(int num) {
    List<Integer> digits = new ArrayList<>();
    while (num > 0) {
        digits.add(num % 10);
