public static int findSmallestInteger(int n) {
    // check if the input is valid
    if (n <= 0) {
        return -1;
    }

    // convert the integer to a string
    String str = String.valueOf(n);
    char[] arr = str.toCharArray();

    // sort the characters in ascending order
    Arrays.sort(arr);

    // build a new string with the sorted characters
    String sortedStr = new String(arr);

    // convert the sorted string back to an integer
    int smallestInteger = Integer.parseInt(sortedStr);

    // return the smallest integer if it is greater than the original input, or -1 otherwise
    return smallestInteger > n ? smallestInteger : -1;
}

